   <body>
     <a class="skip-link" href="#main">Skip to main content</a>
     <div id="root"></div>

     <script>
       const h = (tag, attrs = {}, ...children) => {
         const node = document.createElement(tag);

         for (const [key, value] of Object.entries(attrs)) {
           if (key === "className") {
             node.className = value;
           } else if (key === "textContent") {
             node.textContent = value;
           } else if (key === "htmlFor") {
             node.htmlFor = value;
           } else if (key.startsWith("on") && typeof value === "function") {
             node.addEventListener(key.slice(2).toLowerCase(), value);
           } else if (value === true) {
             node.setAttribute(key, "");
           } else if (value !== false && value != null) {
             node.setAttribute(key, value);
           }
         }

         for (const child of children.flat()) {
           node.append(child instanceof Node ? child : document.createTextNode(String(child)));
         }

         return node;
       };

       function ConsentCheckbox() {
         const helperId = "consent-help";
         const inputId = "consent";

         return h(
           "div",
           { className: "form-field" },
           h(
             "div",
             { className: "checkbox-row" },
             h("input", {
               id: inputId,
               name: "termsConsent",
               type: "checkbox",
               required: true,
               "aria-describedby": helperId,
             }),
             h(
               "label",
               { className: "checkbox-label", htmlFor: inputId },
               "I agree to the Terms of Use",
               h("span", { className: "required", "aria-hidden": "true" }, "*")
             )
           ),
           h("p", { id: helperId, className: "helper" }, "Required to continue.")
         );
       }

       function App() {
         const status = h("p", {
           className: "status",
           id: "form-status",
           "aria-live": "polite",
         });

         const form = h(
           "form",
           { className: "consent-form", novalidate: false },
           h("fieldset", {}, h("legend", {}, "Consent"), ConsentCheckbox()),
           h(
             "div",
             { className: "actions" },
             h("button", { type: "submit" }, "Submit")
           ),
           status
         );

         form.addEventListener("submit", (event) => {
           event.preventDefault();
           status.textContent = "Thanks — your consent has been saved.";
         });

         return h(
           "main",
           { className: "shell", id: "main" },
           h(
             "section",
             { className: "card", "aria-labelledby": "page-title" },
             h("p", { className: "eyebrow", textContent: "Product settings" }),
             h("h1", { id: "page-title", textContent: "Agree to the Terms of Use" }),
             h(
               "p",
               { className: "lead" },
               "Please confirm your consent before continuing."
             ),
             form
           )
         );
       }

       document.getElementById("root").replaceChildren(App());
     </script>
